 catalogResults(q){const job=this.executionFor(q);if(job?.binding?.type!=='discovery')return '';const result=job.result;this.catalogItems=(result?.results||[]).flatMap(source=>(source.items||[]).map(item=>({item,source_id:source.source_id})));if(!this.catalogItems.length)return '';const names={pc_sentinel2_l2a:'Sentinel-2',pc_sentinel1_rtc:'Sentinel-1 RTC',pc_landsat_c2_l2:'Landsat 8/9',earthsearch_sentinel2_l2a:'Earth Search Sentinel-2',earthsearch_cop_dem_glo30:'Copernicus DEM',cdse_sentinel2_l2a:'CDSE Sentinel-2'};return `<section class="ap-catalog-results"><h3>实际检索的影像条目</h3><p>以下为目录元数据，尚未读取像素或执行解译。</p>${this.catalogItems.slice(0,12).map(({item,source_id},i)=>`<article><div><b>${esc(names[source_id]||source_id)}</b><time>${esc(item.datetime?.slice(0,10)||'日期未提供')}</time></div><small>${esc(item.id)}</small><footer><span>${typeof item.cloud_cover==='number'?'场景云量 '+format(item.cloud_cover,2)+'%':source_id==='pc_sentinel1_rtc'?'雷达云量不适用':'未提供场景云量'}</span>${Array.isArray(item.bbox)?`<button data-mc-action="catalog-footprint" data-index="${i}">定位目录包络 ${icon('map')}</button>`:''}</footer></article>`).join('')}</section>`}
