   try{const list=await this.api('/assistant/questions'),oldId=this.selected?.id,oldStatus=this.selected?.status;this.questions=list;if(this.selected)this.selected=list.find(q=>q.id===oldId)||this.selected;this.notify();if(this.selected)await this.fetchExecution(this.selected);if(this.tab==='chat'&&oldStatus==='processing'&&this.selected?.id===oldId&&this.selected?.status==='answered')await this.applyMap(this.selected,{fit:true});if(this.element.isConnected&&this.tab!=='applications'){this.refreshBody();if(oldStatus==='processing'&&this.selected?.id===oldId&&this.selected?.status==='answered')this.revealAnswer()}}
